const RETAINED_SHA = '04b4b49603116046ac475d31a244207aa61054a672aacaffa976a106800961e9'
const failure=e=>({name:e.name??'Error',code:e.code??null,message:String(e.message).slice(0,1024)})
export function query(hex) {
 assert.ok(hex===null||typeof hex==='string'&&/^(?:[0-9a-f]{2})*$/.test(hex)&&hex.length<=24802)
 const value=hex===null?'CAST(NULL AS varbinary(max))':'0x'+hex
 return `DECLARE @v varchar(max) = CONVERT(varchar(max),${value}); SELECT CONVERT(varbinary(max),@v) AS native_bytes; SELECT CONVERT(varbinary(max),CONVERT(nvarchar(max),@v)) AS unicode_units`
}

export function validatePackets(record, expectedSpid, bulk = false) {
  assert.ok(record.packets.length <= MAX_PACKETS)
  const expectedMessages = bulk ? [['out',1],['in',4],['out',7],['in',4]] : [['out',1],['in',4]]
  let size = 0, message = null, inboundSpid = expectedSpid, messages = 0
  for (const p of record.packets) {
    assert.ok(['in','out'].includes(p.direction) && /^(?:[0-9a-f]{2})+$/.test(p.rawHex) && p.rawHex.length <= 65534)
    size += p.rawHex.length / 2
    assert.ok(size <= LIMIT)
    const bytes = Buffer.from(p.rawHex, 'hex')
    assert.ok(bytes.length >= 8 && bytes.readUInt16BE(2) === bytes.length)
    assert.ok(p.direction === 'in' ? bytes[0] === 4 : [1,6,7].includes(bytes[0]))
    assert.ok(bytes[1] === 0 || bytes[1] === 1, 'fixed controlled packet status')
    const spid = bytes.readUInt16BE(4)
    if (p.direction === 'in') {
      if (inboundSpid === undefined) inboundSpid = spid
      assert.equal(spid, inboundSpid, 'consistent inbound connection SPID')
    } else assert.equal(spid, 0, 'fixed outbound SPID')
    assert.equal(bytes[7], 0)
    if (message) {assert.equal(message.direction, p.direction); assert.equal(message.type, bytes[0])}
    else {
      assert.deepEqual([p.direction,bytes[0]], expectedMessages[messages], 'fixed phase message direction/type')
      message = {direction: p.direction, type: bytes[0], packetId: 1}
    }
    assert.equal(bytes[6], message.packetId)
    message.packetId = (message.packetId + 1) & 255
    if (bytes[1] & 1) {message = null; messages++}
  }
  assert.equal(message, null, 'complete retained EOM')
  assert.equal(messages, expectedMessages.length, 'complete fixed phase messages')
  return inboundSpid
}
export function signatures(o,database,serverName) {
 validatePackets(o)
 return {result:hash(JSON.stringify(o.result)),request:requestSignature(o),response:responseSignature(o,database,serverName),framing:fragmentationSignature(o)}
}
export function validate(actual) {
 jsonSize(actual);assert.ok(GOLD,'capture not independently pinned')
 assert.equal(actual.format,1);assert.equal(actual.runs.length,4);assert.equal(actual.containers.length,2);for(const container of actual.containers)assert.equal(container.image,referenceImage)
 assert.equal(actual.provenance.clientVersion,'20.0.0');assert.equal(actual.provenance.nodeVersion,GOLD.nodeVersion)
 assert.ok([GOLD.sourceSha,sourceSha].includes(actual.provenance.sourceSha),'approved source')
 assert.deepEqual(actual.provenance.helpers,HELPER_PINS);assert.deepEqual(actual.provenance.fixtures,FIXTURE_PINS)
 const identities=new Set()
 assert.equal(actual.runs[0].serverName,actual.runs[1].serverName);assert.equal(actual.runs[2].serverName,actual.runs[3].serverName);assert.notEqual(actual.runs[0].serverName,actual.runs[2].serverName)
 for(const run of actual.runs) {
  assert.match(run.database,/^msduck_audit_[0-9a-f]{32}$/);assert.ok(!identities.has(run.database));identities.add(run.database)
  assert.equal(run.observations.length,inputs.length)
  const rows=run.version.result.sets[0].rows;assert.equal(rows.length,1);assert.deepEqual(rows[0],['17.0.4065.4',run.database,run.serverName,profiles.utf8])
  assert.deepEqual(versionFacts(run),GOLD.version)
  let spid
  for(const [i,o] of run.observations.entries()) {
   spid=validatePackets(o,spid);assert.equal(o.input,inputs[i]);assert.equal(o.sql,query(inputs[i]));assert.deepEqual(signatures(o,run.database,run.serverName),GOLD.observations[i])
  }
 }
 assert.ok(isDeepStrictEqual(actual.comparisons,actual.runs.slice(1).map(r=>compare(r,actual.runs[0]))),'complete raw comparisons')
}
export function versionFacts(run) {
 validatePackets(run.version)
 const result=structuredClone(run.version.result);result.sets[0].rows[0]=['17.0.4065.4','@DATABASE@','@SERVER@',profiles.utf8]
 return {result:hash(JSON.stringify(result)),request:requestSignature(run.version),response:responseSignature(run.version,run.database,run.serverName),framing:fragmentationSignature(run.version)}
}
export async function validateRetained(){const bytes=await readCaptureFile(fixture);assert.equal(hash(bytes),RETAINED_SHA);validate(JSON.parse(bytes));return bytes}
export async function save(raw,output,compareRetained=true,annotations={}) {
 await guardOutput(output);await guardOutput(output+'.comparison.json');await mkdir(dirname(output),{recursive:true})
 const size=jsonSize(raw);await writeFile(output,JSON.stringify(raw)+(size<CAPTURE_LIMIT?'\n':''),{flag:'wx'})
 let expected;try{if(compareRetained)expected=JSON.parse((await readCaptureFile(fixture)).toString())}catch(e){if(e.code!=='ENOENT')throw e}
 let comparison,err
 try{comparison={...annotations,retained:!!expected,differences:expected?compare(raw,expected):[]};jsonSize(comparison)}catch(e){err=e;comparison={...annotations,retained:!!expected,differencesOmitted:true,failure:failure(e)}}
 const comparisonSize=jsonSize(comparison);await writeFile(output+'.comparison.json',JSON.stringify(comparison)+(comparisonSize<CAPTURE_LIMIT?'\n':''),{flag:'wx'})
 if(err)throw err
}
// Derived comparisons must never prevent retention of bounded observations.
export async function finalize(raw,output,compareRetained=true) {
 let comparisons
 try {
  comparisons=raw.runs.slice(1).map(run=>compare(run,raw.runs[0]))
  jsonSize({...raw,comparisons})
 } catch(error) {
  await save(raw,output,compareRetained,{interRunComparison:{omitted:true,failure:failure(error)}})
  throw error
 }
 raw.comparisons=comparisons
 await save(raw,output,compareRetained)
}
export async function testRetention(output) {
 await guardOutput(output);await guardOutput(output+'.comparison.json')
 const raw={runs:[{value:'a'.repeat(20*1024*1024)},{value:'b'.repeat(20*1024*1024)}]}
 assert.ok(jsonSize(raw)<CAPTURE_LIMIT)
 await assert.rejects(finalize(raw,output,false),{message:'bounded serialized capture'})
 assert.ok(!Object.hasOwn(raw,'comparisons'))
 assert.deepEqual(JSON.parse(await readCaptureFile(output)),raw)
 const sidecar=JSON.parse(await readCaptureFile(output+'.comparison.json'))
 assert.equal(sidecar.interRunComparison.omitted,true)
 assert.ok(sidecar.interRunComparison.failure)
 assert.equal(sidecar.retained,false);assert.deepEqual(sidecar.differences,[])
 await unlink(output);await unlink(output+'.comparison.json')
}
