export function validateEofControls(actual) {
 jsonSize(actual);assert.equal(actual.format,1);assert.equal(actual.runs.length,4);assert.equal(actual.containers.length,2)
 assert.ok([EOF_INITIAL_SOURCE_SHA,'e9713f72ceb80509228de085644a5a42636bf267ac889656c5deccdf35e538d7',sourceSha].includes(actual.provenance.sourceSha));assert.equal(actual.provenance.clientVersion,'20.0.0');assert.equal(actual.provenance.nodeVersion,GOLD.nodeVersion);assert.deepEqual(actual.provenance.helpers,HELPER_PINS);assert.deepEqual(actual.provenance.fixtures,FIXTURE_PINS)
 for(const container of actual.containers)assert.equal(container.image,referenceImage)
 assert.equal(actual.runs[0].serverName,actual.runs[1].serverName);assert.equal(actual.runs[2].serverName,actual.runs[3].serverName);assert.notEqual(actual.runs[0].serverName,actual.runs[2].serverName)
 const databases=new Set();let gold
 for(const run of actual.runs) {
  assert.ok(!databases.has(run.database));databases.add(run.database)
  assert.deepEqual(versionFacts(run),GOLD.version)
  assert.deepEqual(run.version.result.sets[0].rows[0],['17.0.4065.4',run.database,run.serverName,profiles.utf8])
  assert.equal(run.observations.length,eofControls.length)
  const pins=[];let spid
  for(const [i,o] of run.observations.entries()) {
   const [input,units]=eofControls[i];assert.equal(o.input,input);assert.equal(o.sql,query(input))
   spid=validatePackets(o,spid);pins.push(signatures(o,run.database,run.serverName))
   const {sets,errors,info}=o.result;assert.equal(sets.length,2);assert.deepEqual(info,[])
   for(const [j,set] of sets.entries())assert.deepEqual(set.columns,[{name:j===0?'native_bytes':'unicode_units',type:'VarBinary',length:65535,precision:null,scale:null,flags:33,collation:null}])
   assert.deepEqual(sets[0].rows,[[{kind:'binary',value:input}]])
   if(units===null){assert.equal(errors.length,1);assert.equal(errors[0].number,9833);assert.equal(errors[0].state,2);assert.equal(errors[0].class,16);assert.deepEqual(sets[1].rows,[])}
   else{assert.deepEqual(errors,[]);assert.deepEqual(sets[1].rows,[[{kind:'binary',value:units}]])}
  }
  assert.deepEqual(pins,EOF_GOLD,'frozen complete EOF pins');if(gold)assert.deepEqual(pins,gold,'all complete decoded/request/response/framing pins agree');else gold=pins
 }
 assert.ok(isDeepStrictEqual(actual.comparisons,actual.runs.slice(1).map(r=>compare(r,actual.runs[0]))),'complete raw comparisons')
 return gold
}
export async function main(args=process.argv.slice(2)) {
 if(args[0]==='--test-retention'){assert.equal(args.length,2);await testRetention(resolve(args[1]));console.log('comparison overflow retains bounded raw observations');return}
 if(args[0]==='--replay-eof-controls'){assert.equal(args.length,2);validateEofControls(JSON.parse(await readCaptureFile(resolve(args[1]))));console.log('retained EOF controls validated');return}
 if(args[0]==='--replay-fixture'){assert.equal(args.length,1);await validateRetained();console.log('retained stored UTF8 validated');return}
 const eof=args[0]==='--eof-controls';if(eof)args=args.slice(1)
 assert.ok(args.length<=1);const output=resolve(args[0]??(eof?'artifacts/compatibility/stored-utf8-projection/eof-controls.json':'artifacts/compatibility/stored-utf8-projection/capture.json'))
 const selectedInputs=eof?eofControls.map(control=>control[0]):inputs
 assert.notEqual(output,fixture);await guardOutput(output);await guardOutput(output+'.comparison.json')
 for(const [name,sha] of Object.entries(HELPER_PINS))assert.equal(hash(await readFile(new URL(name,import.meta.url))),sha)
 for(const [name,sha] of Object.entries(FIXTURE_PINS))assert.equal(hash(await readFile(new URL('../reference/'+name,import.meta.url))),sha)
 const raw={format:1,provenance:{sourceSha,nodeVersion:process.versions.node,clientVersion,helpers:HELPER_PINS,fixtures:FIXTURE_PINS},containers:[],runs:[]},retained=budget()
 try{
  for(let n=0;n<2;n++)await withReferenceContainer(async(config,container)=>{
   raw.containers.push({image:container.image})
   for(let d=0;d<2;d++)await isolatedReference(config,async(initial)=>{
    const run={observations:[]};raw.runs.push(run)
    run.version=await exchange(initial,()=>capture(initial,"SELECT CAST(SERVERPROPERTY('ProductVersion') AS nvarchar(128)) AS version, DB_NAME() AS database_name, CAST(SERVERPROPERTY('ServerName') AS nvarchar(128)) AS server_name, CAST(DATABASEPROPERTYEX(DB_NAME(),'Collation') AS nvarchar(128)) AS database_collation"),retained)
    const [version,db,serverName,collation]=run.version.result.sets[0].rows[0];assert.equal(version,'17.0.4065.4');assert.equal(collation,profiles.utf8);run.database=db;run.serverName=serverName
    const connection=await connect({...config,options:{...config.options,database:db,packetSize:512,requestTimeout:10000}})
    try{for(const input of selectedInputs){const sql=query(input),o={input,sql};run.observations.push(o);Object.assign(o,await exchange(connection,()=>capture(connection,sql),retained));assert.ok(!o.result.traceFailure&&!o.result.captureBudgetFailure);console.log(JSON.stringify({run:raw.runs.length,inputBytes:input===null?null:input.length/2,observations:run.observations.length,errors:o.result.errors.map(e=>e.number)}))}}finally{connection.close()}
   },{connect,command:(connection,sql)=>command(connection,sql.startsWith('CREATE DATABASE ')?sql+' COLLATE '+profiles.utf8:sql)})
  },{image:referenceImage})
 }catch(e){await save(raw,output,!eof,{captureFailure:failure(e)});throw e}
 await finalize(raw,output,!eof);const pins=eof?validateEofControls(raw):undefined;if(!eof)validate(raw);console.log(JSON.stringify({output,observations:selectedInputs.length,runs:raw.runs.length,sourceSha,eofPins:pins}))
}
if(process.argv[1]&&resolve(process.argv[1])===source)await main()
